package Assignments;

public class SwitchCase {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int a=3;
		switch(a)
		{
		case 1:System.out.println("chrome browser launch");
		break;
		case 2:System.out.println("firefox browser launch");
		break;
		case 3:System.out.println("safari browser launch");
		break;
		case 4:System.out.println("edge browser launch");
		break;
		
		default:System.out.println("your selection is wrong");
		
		}
		
	}

}
